	goto fail_alloc_staging;
}

if (!(root->interactive = wlr_scene_tree_create(&root_scene->node))) {
	goto fail_alloc_interactive;
}

if (!(root->noninteractive = wlr_scene_tree_create(&root_scene->node))) {
	goto fail_alloc_noninteractive;
}

if (!(root->root_scene = wlr_scene_create())) {
	goto fail_alloc_root_scene;
}

return root;

